function periodPicker(): string {global $pdo,$user,$page;if(!$user)return ''; $s=$pdo->query('SELECT period FROM global_parameter_versions ORDER BY period DESC');$periods=$s->fetchAll(PDO::FETCH_COLUMN);if(!$periods)return ''; $current=$_GET['period']??$periods[0];$periodPages=['parameters','variables-grid','variables','calculate','payslips','summary','book','lre','payslip','parameters-edit','parameter-advanced','attendance'];$target=in_array($page,$periodPages,true)?$page:'variables-grid';$options='';foreach($periods as $period)$options.='<option value="'.h($period).'"'.($period===$current?' selected':'').'>'.h($period).'</option>';return '<form class="period-picker" method="get" action="index.php"><input type="hidden" name="page" value="'.h($target).'"><label for="active-period">Período</label><select id="active-period" name="period" onchange="this.form.submit()">'.$options.'</select></form>'; }
function dateFormatScript(): string {return '<script>document.querySelectorAll(".employee-grid input[type=date]").forEach(function(input){input.setAttribute("lang","es-CL");});document.querySelectorAll(".period-picker").forEach(function(form){var original=form.querySelector("select[name=period]");if(!original)return;var values=[].map.call(original.options,function(option){return option.value;});var current=original.value.split("-");var years=[];values.forEach(function(value){var year=value.slice(0,4);if(years.indexOf(year)<0)years.push(year);});var yearSelect=document.createElement("select");yearSelect.setAttribute("aria-label","Año");years.forEach(function(year){var option=document.createElement("option");option.value=year;option.textContent=year;option.selected=year===current[0];yearSelect.appendChild(option);});var monthSelect=document.createElement("select");monthSelect.setAttribute("aria-label","Mes");var names={"01":"Enero","02":"Febrero","03":"Marzo","04":"Abril","05":"Mayo","06":"Junio","07":"Julio","08":"Agosto","09":"Septiembre","10":"Octubre","11":"Noviembre","12":"Diciembre"};function fill(){var selected=monthSelect.value;monthSelect.innerHTML="";values.filter(function(value){return value.slice(0,4)===yearSelect.value;}).forEach(function(value){var month=value.slice(5);var option=document.createElement("option");option.value=month;option.textContent=names[month]||month;option.selected=month===selected||month===current[1];monthSelect.appendChild(option);});}function submit(){var value=yearSelect.value+"-"+monthSelect.value;original.value=value;form.submit();}form.querySelector("label").textContent="Año";original.style.display="none";form.appendChild(yearSelect);var label=document.createElement("label");label.setAttribute("for","period-month");label.textContent="Mes";monthSelect.id="period-month";form.appendChild(label);form.appendChild(monthSelect);fill();yearSelect.addEventListener("change",function(){fill();submit();});monthSelect.addEventListener("change",submit);});</script>'; }
 function sheetNavigation(): string { global $user,$page; if(!$user)return ''; $period=$_GET['period']??'';$items=[['01_Parametros_Previred','parameters'],['02_BD_Trabajadores','employees'],['03_Variables_y_Calculos','periods&sheet=variables-grid'],['04_Liquidacion_Formato','periods&sheet=payslips'],['09_Registrar_Asistencia','attendance'],['10_Libro_Asistencia','attendance-summary'],['11_Préstamos_Empresa','loans']];if(($user['role']??'')==='admin')$items[]=['08_Crear_Empresa','company-new'];$html='<nav class="sheet-nav" aria-label="Módulos del libro">';foreach($items as $item){$base=explode('&',$item[1])[0];$active=(($page===$base)||($item[1]==='attendance-summary'&&$page==='attendance-summary'))?' active':'';$url='?page='.$item[1].($period?'&period='.rawurlencode($period):'');$html.='<a href="'.$url.'" class="sheet-tab'.$active.'">'.h($item[0]).'</a>';}return $html.'</nav>'; }
function layout(string $title, string $body): void {global $user,$page,$periodService;
  $parameterPage=in_array($page,['parameters-edit','parameter-advanced'],true);
  $monthlyPage=in_array($page,['variables-grid','attendance','attendance-summary','parameters-edit','parameter-advanced'],true);
  $period=(string)($_GET['period']??'');$closed=false;
  if($user&&$monthlyPage&&$periodService->ready()&&preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$period))$closed=$periodService->isClosed($period);
  if($closed)$body='<p class="notice">Período cerrado para todas las empresas. La información se conserva para consulta.</p>'.$body;
  if($user&&(($parameterPage&&!periodAdministrator())||$closed)){
    $disable=static fn($html)=>preg_replace('~<(input|select|textarea|button)\b~i','<$1 disabled',$html);
    $body=preg_replace_callback('~<form\b(?=[^>]*method=["\']?post\b)[^>]*>.*?</form>~is',static fn($match)=>$disable($match[0]),$body);
    $body=preg_replace('~<(input|select|textarea|button)\b(?=[^>]*\bform=["\']?excel-grid-form\b)~i','<$1 disabled',$body);
  }
  $readOnlyScript=($user&&(($parameterPage&&!periodAdministrator())||$closed))?'<script>document.querySelectorAll("main form[method=post] input,main form[method=post] select,main form[method=post] textarea,main form[method=post] button,main [form=excel-grid-form]").forEach(function(el){el.disabled=true;});</script>':'';
echo '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).' · Remuneraciones</title><link rel="stylesheet" href="style.css"></head><body class="page-'.h($page).($closed?' period-locked':'').'">'.($user?'<header class="app-header"><strong>Remuneraciones</strong><span>'.h($title).'</span>'.companyPicker().periodPicker().'<a href="?page=profile">Mi perfil</a><a href="?page=company-new">Nueva empresa</a>'.(($user['role']??'')==='admin'?'<a href="?page=users">Usuarios</a>':'').(($user['global_role']??'none')==='admin'?'<a href="?page=global-users">Solicitudes</a>':'').'<a href="?page=logout">Salir</a></header>':'').'<main>'.$body.'</main>'.sheetNavigation().dateFormatScript().$readOnlyScript.'</body></html>';}
